from abc import ABC, abstractmethod


class Employee(ABC):
    def check_in(self):  # concrete: shared as-is
        print("Checked in")

    @abstractmethod
    def calculate_salary(self):
        pass  # abstract: subclasses must implement


class Intern(Employee):
    def calculate_salary(self):
        return 1000


if __name__ == "__main__":
    emp = Intern()
    emp.check_in()
    print(emp.calculate_salary())

