#include <iostream>
using namespace std;

class Employee {
public:
    void checkIn() { // concrete: shared as-is
        cout << "Checked in" << endl;
    }

    virtual double calculateSalary() = 0; // abstract: subclasses must implement
    virtual ~Employee() {}
};

class Intern : public Employee {
public:
    double calculateSalary() override {
        return 1000;
    }
};

int main() {
    Employee* emp = new Intern();
    emp->checkIn();
    cout << emp->calculateSalary() << endl;
    delete emp;
    return 0;
}

