abstract class Employee {
    protected String name;
    protected String id;

    Employee(String name, String id) {
        this.name = name;
        this.id = id;
    }

    // Concrete method: shared by EVERY employee, no need to override
    public void checkIn() {
        System.out.println(name + " checked in for the day");
    }

    // Abstract method: each employee type MUST provide its own version
    public abstract double calculateSalary();

    public String getName() {
        return name;
    }
}

class FullTimeEmployee extends Employee {
    private double monthlySalary;

    FullTimeEmployee(String name, String id, double monthlySalary) {
        super(name, id);
        this.monthlySalary = monthlySalary;
    }

    @Override
    public double calculateSalary() {
        return monthlySalary;
    }
}

class ContractEmployee extends Employee {
    private double hourlyRate;
    private int hoursWorked;

    ContractEmployee(String name, String id, double hourlyRate, int hoursWorked) {
        super(name, id);
        this.hourlyRate = hourlyRate;
        this.hoursWorked = hoursWorked;
    }

    @Override
    public double calculateSalary() {
        return hourlyRate * hoursWorked;
    }
}

public class Main {
    public static void main(String[] args) {
        Employee emp1 = new FullTimeEmployee("Asha", "E1", 60000);
        Employee emp2 = new ContractEmployee("Raj", "E2", 50, 120);

        emp1.checkIn(); // shared, inherited directly, never rewritten
        emp2.checkIn(); // shared, inherited directly, never rewritten

        System.out.println(emp1.getName() + "'s salary: " + emp1.calculateSalary());
        System.out.println(emp2.getName() + "'s salary: " + emp2.calculateSalary());

        // Employee emp3 = new Employee("X", "E3"); // would NOT compile: Employee is abstract
    }
}

