from abc import ABC, abstractmethod


class Employee(ABC):
    def __init__(self, name, emp_id):
        self.name = name
        self.emp_id = emp_id

    def check_in(self):
        # Concrete method: shared by EVERY employee, no need to override
        print(f"{self.name} checked in for the day")

    @abstractmethod
    def calculate_salary(self):
        pass  # each employee type MUST provide its own version


class FullTimeEmployee(Employee):
    def __init__(self, name, emp_id, monthly_salary):
        super().__init__(name, emp_id)
        self.monthly_salary = monthly_salary

    def calculate_salary(self):
        return self.monthly_salary


class ContractEmployee(Employee):
    def __init__(self, name, emp_id, hourly_rate, hours_worked):
        super().__init__(name, emp_id)
        self.hourly_rate = hourly_rate
        self.hours_worked = hours_worked

    def calculate_salary(self):
        return self.hourly_rate * self.hours_worked


if __name__ == "__main__":
    emp1 = FullTimeEmployee("Asha", "E1", 60000)
    emp2 = ContractEmployee("Raj", "E2", 50, 120)

    emp1.check_in()  # shared, inherited directly, never rewritten
    emp2.check_in()  # shared, inherited directly, never rewritten

    print(f"{emp1.name}'s salary: {emp1.calculate_salary()}")
    print(f"{emp2.name}'s salary: {emp2.calculate_salary()}")

    # emp3 = Employee("X", "E3")  # would raise TypeError: Can't instantiate abstract class

