#include <iostream>
#include <string>
using namespace std;

class Employee {
protected:
    string name;
    string id;

public:
    Employee(string name, string id) : name(name), id(id) {}

    // Concrete method: shared by EVERY employee, no need to override
    void checkIn() {
        cout << name << " checked in for the day" << endl;
    }

    // Pure virtual: each employee type MUST provide its own version
    virtual double calculateSalary() = 0;

    string getName() {
        return name;
    }

    virtual ~Employee() {}
};

class FullTimeEmployee : public Employee {
private:
    double monthlySalary;
public:
    FullTimeEmployee(string name, string id, double monthlySalary)
        : Employee(name, id), monthlySalary(monthlySalary) {}

    double calculateSalary() override {
        return monthlySalary;
    }
};

class ContractEmployee : public Employee {
private:
    double hourlyRate;
    int hoursWorked;
public:
    ContractEmployee(string name, string id, double hourlyRate, int hoursWorked)
        : Employee(name, id), hourlyRate(hourlyRate), hoursWorked(hoursWorked) {}

    double calculateSalary() override {
        return hourlyRate * hoursWorked;
    }
};

int main() {
    Employee* emp1 = new FullTimeEmployee("Asha", "E1", 60000);
    Employee* emp2 = new ContractEmployee("Raj", "E2", 50, 120);

    emp1->checkIn(); // shared, inherited directly, never rewritten
    emp2->checkIn(); // shared, inherited directly, never rewritten

    cout << emp1->getName() << "'s salary: " << emp1->calculateSalary() << endl;
    cout << emp2->getName() << "'s salary: " << emp2->calculateSalary() << endl;

    delete emp1;
    delete emp2;
    return 0;
}
